    76→// ParseHookInput parses Claude Code hook input from stdin.
    77→func (c *ClaudeCodeAgent) ParseHookInput(hookType agent.HookType, reader io.Reader) (*agent.HookInput, error) {
    78→	data, err := io.ReadAll(reader)
    79→	if err != nil {
    80→		return nil, fmt.Errorf("failed to read input: %w", err)
    81→	}
    82→
    83→	if len(data) == 0 {
    84→		return nil, errors.New("empty input")
    85→	}
    86→
    87→	input := &agent.HookInput{
    88→		HookType:  hookType,
    89→		Timestamp: time.Now(),
    90→		RawData:   make(map[string]interface{}),
    91→	}
    92→
    93→	// Parse based on hook type
    94→	switch hookType {
    95→	case agent.HookSessionStart, agent.HookUserPromptSubmit, agent.HookStop:
    96→		var raw sessionInfoRaw
    97→		if err := json.Unmarshal(data, &raw); err != nil {
    98→			return nil, fmt.Errorf("failed to parse session info: %w", err)
    99→		}
   100→		input.SessionID = raw.SessionID
   101→		input.SessionRef = raw.TranscriptPath
   102→
   103→	case agent.HookPreToolUse:
   104→		var raw taskHookInputRaw
   105→		if err := json.Unmarshal(data, &raw); err != nil {
   106→			return nil, fmt.Errorf("failed to parse pre-tool input: %w", err)
   107→		}
   108→		input.SessionID = raw.SessionID
   109→		input.SessionRef = raw.TranscriptPath
   110→		input.ToolUseID = raw.ToolUseID
   111→		input.ToolInput = raw.ToolInput
   112→
   113→	case agent.HookPostToolUse:
   114→		var raw postToolHookInputRaw
   115→		if err := json.Unmarshal(data, &raw); err != nil {
   116→			return nil, fmt.Errorf("failed to parse post-tool input: %w", err)
   117→		}
   118→		input.SessionID = raw.SessionID
   119→		input.SessionRef = raw.TranscriptPath
   120→		input.ToolUseID = raw.ToolUseID
   121→		input.ToolInput = raw.ToolInput
   122→		// Store agent ID in raw data for Task tool results
   123→		if raw.ToolResponse.AgentID != "" {
   124→			input.RawData["agent_id"] = raw.ToolResponse.AgentID
   125→		}
   126→	}
   127→
   128→	return input, nil
   129→}
