   168→// ReadSession reads a session from Claude's storage (JSONL transcript file).
   169→// The session data is stored in NativeData as raw JSONL bytes.
   170→// ModifiedFiles is computed by parsing the transcript.
   171→func (c *ClaudeCodeAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
   172→	if input.SessionRef == "" {
   173→		return nil, errors.New("session reference (transcript path) is required")
   174→	}
   175→
   176→	// Read the raw JSONL file
   177→	data, err := os.ReadFile(input.SessionRef)
   178→	if err != nil {
   179→		return nil, fmt.Errorf("failed to read transcript: %w", err)
   180→	}
   181→
   182→	// Parse to extract computed fields
   183→	lines, err := ParseTranscript(data)
   184→	if err != nil {
   185→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
   186→	}
   187→
   188→	return &agent.AgentSession{
   189→		SessionID:     input.SessionID,
   190→		AgentName:     c.Name(),
   191→		SessionRef:    input.SessionRef,
   192→		StartTime:     time.Now(),
   193→		NativeData:    data,
   194→		ModifiedFiles: ExtractModifiedFiles(lines),
   195→	}, nil
   196→}
