   198→// WriteSession writes a session to Claude's storage (JSONL transcript file).
   199→// Uses the NativeData field which contains raw JSONL bytes.
   200→// The session must have been created by Claude Code (AgentName check).
   201→func (c *ClaudeCodeAgent) WriteSession(session *agent.AgentSession) error {
   202→	if session == nil {
   203→		return errors.New("session is nil")
   204→	}
   205→
   206→	// Verify this session belongs to Claude Code
   207→	if session.AgentName != "" && session.AgentName != c.Name() {
   208→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
   209→	}
   210→
   211→	if session.SessionRef == "" {
   212→		return errors.New("session reference (transcript path) is required")
   213→	}
   214→
   215→	if len(session.NativeData) == 0 {
   216→		return errors.New("session has no native data to write")
   217→	}
   218→
   219→	// Write the raw JSONL data
   220→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
   221→		return fmt.Errorf("failed to write transcript: %w", err)
   222→	}
   223→
   224→	return nil
   225→}
