   249→// TruncateAtUUID returns a new session truncated at the given UUID (inclusive).
   250→// This is used for rewind operations to restore transcript state.
   251→// Requires NativeData to be populated.
   252→func (c *ClaudeCodeAgent) TruncateAtUUID(session *agent.AgentSession, uuid string) (*agent.AgentSession, error) {
   253→	if session == nil {
   254→		return nil, errors.New("session is nil")
   255→	}
   256→
   257→	if len(session.NativeData) == 0 {
   258→		return nil, errors.New("session has no native data")
   259→	}
   260→
   261→	if uuid == "" {
   262→		// No truncation needed, return copy
   263→		return &agent.AgentSession{
   264→			SessionID:     session.SessionID,
   265→			AgentName:     session.AgentName,
   266→			RepoPath:      session.RepoPath,
   267→			SessionRef:    session.SessionRef,
   268→			StartTime:     session.StartTime,
   269→			NativeData:    session.NativeData,
   270→			ModifiedFiles: session.ModifiedFiles,
   271→		}, nil
   272→	}
   273→
   274→	// Parse, truncate, re-serialize
   275→	lines, err := ParseTranscript(session.NativeData)
   276→	if err != nil {
   277→		return nil, fmt.Errorf("failed to parse transcript: %w", err)
   278→	}
   279→
   280→	truncated := TruncateAtUUID(lines, uuid)
   281→
   282→	newData, err := SerializeTranscript(truncated)
   283→	if err != nil {
   284→		return nil, fmt.Errorf("failed to serialize truncated transcript: %w", err)
   285→	}
   286→
   287→	return &agent.AgentSession{
   288→		SessionID:     session.SessionID,
   289→		AgentName:     session.AgentName,
   290→		RepoPath:      session.RepoPath,
   291→		SessionRef:    session.SessionRef,
   292→		StartTime:     session.StartTime,
   293→		NativeData:    newData,
   294→		ModifiedFiles: ExtractModifiedFiles(truncated),
   295→	}, nil
   296→}
